import{BUILDINGS}from"../data/buildings.js";import{LOCATIONS}from"../data/locations.js";export class World{constructor(){this.width=2400;this.height=1600;this.buildings=BUILDINGS;this.locations=LOCATIONS;this.roads=[{x:0,y:360,w:2400,h:150},{x:1050,y:0,w:150,h:1600},{x:0,y:1030,w:2400,h:120}]}update(){}isBlocked(x,y,r=14){if(x-r<20||y-r<20||x+r>this.width-20||y+r>this.height-20)return true;return this.buildings.some(b=>x+r>b.x&&x-r<b.x+b.w&&y+r>b.y&&y-r<b.y+b.h)}draw(ctx,c){ctx.save();ctx.translate(-c.x,-c.y);ctx.fillStyle="#9bd67b";ctx.fillRect(0,0,this.width,this.height);for(const r of this.roads){ctx.fillStyle="#68727d";ctx.fillRect(r.x,r.y,r.w,r.h)}for(const b of this.buildings){ctx.fillStyle=b.color;ctx.fillRect(b.x,b.y,b.w,b.h);ctx.fillStyle="#263247";ctx.font="bold 16px system-ui";ctx.fillText(b.name,b.x+12,b.y+25)}for(let x=80;x<2300;x+=180)for(let y=70;y<1500;y+=200){if(this.roads.some(r=>x>r.x&&x<r.x+r.w&&y>r.y&&y<r.y+r.h))continue;ctx.fillStyle="#8b5a3c";ctx.fillRect(x-4,y+10,8,28);ctx.fillStyle="#3d9b5b";ctx.beginPath();ctx.arc(x,y,23,0,Math.PI*2);ctx.fill()}ctx.restore()}}
